ALTER TABLE settings ALTER COLUMN radius_m TYPE double precision;
ALTER TABLE settings ALTER COLUMN radius_m SET DEFAULT 91.44;
ALTER TABLE settings DROP CONSTRAINT settings_radius_m_check;
ALTER TABLE settings ADD CHECK(radius_m BETWEEN 3.048 AND 10000);
UPDATE settings SET radius_m=91.44 WHERE latitude IS NULL AND longitude IS NULL AND radius_m=300;
UPDATE settings SET geofence_enabled=true;
ALTER TABLE settings ALTER COLUMN geofence_enabled SET DEFAULT true;
CREATE TABLE trusted_kiosks (id uuid PRIMARY KEY, name text NOT NULL, token_hash text UNIQUE NOT NULL, registered_by uuid NOT NULL REFERENCES admins(id), registered_at timestamptz NOT NULL DEFAULT clock_timestamp(), expires_at timestamptz NOT NULL, revoked_at timestamptz);
CREATE TABLE kiosk_audit (id uuid PRIMARY KEY, kiosk_id uuid NOT NULL REFERENCES trusted_kiosks(id), admin_id uuid NOT NULL REFERENCES admins(id), action text NOT NULL, at timestamptz NOT NULL DEFAULT clock_timestamp());
ALTER TABLE punches ADD COLUMN approximate_distance_m integer;
ALTER TABLE punches ADD COLUMN accuracy_m integer;
ALTER TABLE punches ADD COLUMN kiosk_id uuid REFERENCES trusted_kiosks(id);
CREATE TABLE location_attempts (id uuid PRIMARY KEY, token_hash text UNIQUE NOT NULL, employee_id uuid NOT NULL REFERENCES employees(id), type text NOT NULL CHECK(type IN ('in','lunch_out','lunch_in','out')), status text NOT NULL, approximate_distance_m integer, accuracy_m integer, kiosk_id uuid REFERENCES trusted_kiosks(id), at timestamptz NOT NULL DEFAULT clock_timestamp(), expires_at timestamptz NOT NULL DEFAULT clock_timestamp()+interval '2 minutes', retries integer NOT NULL DEFAULT 0, punch_id uuid REFERENCES punches(id));
CREATE TABLE punch_reviews (id uuid PRIMARY KEY, punch_id uuid NOT NULL REFERENCES punches(id), decision text NOT NULL CHECK(decision IN ('approved','follow_up')), reason text NOT NULL, admin_id uuid NOT NULL REFERENCES admins(id), correction_count integer NOT NULL, previous_decision text, at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE INDEX location_attempts_pending ON location_attempts(at) WHERE punch_id IS NULL;
CREATE INDEX punch_reviews_latest ON punch_reviews(punch_id,at);
CREATE OR REPLACE VIEW effective_punches AS SELECT p.id,p.employee_id,COALESCE(c.corrected_value->>'type',p.type) AS type,COALESCE((c.corrected_value->>'at')::timestamptz,p.at) AS at,p.location_check,p.created_by,p.reason,p.approximate_distance_m,p.accuracy_m,p.kiosk_id,r.decision AS review_decision FROM punches p LEFT JOIN LATERAL (SELECT corrected_value FROM corrections WHERE punch_id=p.id ORDER BY at DESC,id DESC LIMIT 1) c ON true LEFT JOIN LATERAL (SELECT decision FROM punch_reviews WHERE punch_id=p.id AND correction_count=(SELECT count(*) FROM corrections WHERE punch_id=p.id) ORDER BY at DESC,id DESC LIMIT 1) r ON true;
CREATE TABLE attempt_reviews (id uuid PRIMARY KEY, attempt_id uuid NOT NULL REFERENCES location_attempts(id), admin_id uuid NOT NULL REFERENCES admins(id), reason text NOT NULL, at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE INDEX attempt_reviews_by_attempt ON attempt_reviews(attempt_id);
